import{_ as e,c as o,o as t,a2 as a}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"Sitemap & SEO","description":"","frontmatter":{"sidebarPos":9,"sidebarTitle":"Sitemap & SEO","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/sitemap-and-seo.md","filePath":"guide/cms/sitemap-and-seo.md","lastUpdated":1785337537000}'),s={name:"guide/cms/sitemap-and-seo.md"},i=a('<h1 id="sitemap-seo" tabindex="-1">Sitemap &amp; SEO <a class="header-anchor" href="#sitemap-seo" aria-label="Permalink to &quot;Sitemap &amp; SEO&quot;">​</a></h1><h2 id="sitemap" tabindex="-1">Sitemap <a class="header-anchor" href="#sitemap" aria-label="Permalink to &quot;Sitemap&quot;">​</a></h2><p><strong>Build</strong> (<code>CmsSitemapBuildService</code>): all <code>UrlRoute</code> rows with <code>kind = page_public</code>, gated + published/visible models, absolute locs via public site URL helpers. Optional <code>CmsSitemapableItem</code> morph overrides <code>changefreq</code> / <code>priority</code>. Hreflang alternates group by urlable.</p><p><strong>Cache</strong> (<code>CmsSitemapCacheService</code>): committed XML in <code>Cache::forever</code> (<code>cms_sitemap.cache_key</code>). Public requests only <strong>read</strong> the cache.</p><p><strong>Public route</strong>: <code>GET /sitemap.xml</code> → <code>PublicSitemapController</code> (via <a href="./public-routing">Public routing</a> catalog). Rebuild with <code>php artisan cms:sitemap:rebuild</code> or the panel commit tool / <code>RebuildCmsSitemapJob</code>.</p><p>Browser view: committed XML includes <code>&lt;?xml-stylesheet href=&quot;/sitemap.xsl&quot;?&gt;</code>; <code>GET /sitemap.xsl</code> → <code>PublicSitemapXslController</code> (human-readable table). Crawlers ignore the stylesheet.</p><p>Panel dry-run returns XSLT HTML when PHP <code>ext-xsl</code> is available (<code>CmsSitemapXsltService</code>), plus the raw stylesheet for a browser-side fallback when the extension is missing.</p><p><code>build_on_cache_miss</code> (default false): optional sync build on first miss; otherwise empty valid <code>&lt;urlset&gt;</code> until commit.</p><h2 id="robots-txt" tabindex="-1">Robots.txt <a class="header-anchor" href="#robots-txt" aria-label="Permalink to &quot;Robots.txt&quot;">​</a></h2><p><code>GET /robots.txt</code> → <code>RobotsTxtController</code> when <code>cms_seo.robots.route_enabled</code>. Body from System Settings (when enabled) or <code>cms_seo.robots.global_robots_txt</code>. Staging noindex can force disallow-all (<code>cms_seo</code>).</p><h2 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h2><p><code>modularous.cms_sitemap</code>, <code>modularous.cms_seo</code>. See <a href="./configuration">Configuration</a>.</p>',12),c=[i];function d(r,l,n,m,p,u){return t(),o("div",null,c)}const _=e(s,[["render",d]]);export{b as __pageData,_ as default};
